<?php require_once __DIR__.'/comman/auth.php'; $pageTitle="System Settings"; require __DIR__.'/comman/header.php'; require __DIR__.'/comman/sidebar.php'; ?><div class="content-wrapper"><section class="content-header"><div class="container-fluid"><div class="row mb-2"><div class="col-sm-8"><h1><?=h($pageTitle)?></h1></div></div><?php if($flash):?><div class="alert alert-<?=h($flash[0])?>"><?=h($flash[1])?></div><?php endif;?></div></section><section class="content"><div class="container-fluid"><?php if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$p=$_POST['new_password']??'';$c=$_POST['confirm_password']??'';if($p==='' )flash('info','No password change requested.');elseif(strlen($p)<10||$p!==$c)flash('danger','Password must be at least 10 characters and match.');else{write_json(CMS_DATA.'/auth.json',['password_hash'=>password_hash($p,PASSWORD_DEFAULT),'updated_at'=>date('c')]);flash('success','Admin password changed.');}redirect_admin('settings.php');}?><div class="card"><div class="card-header"><h3 class="card-title">Admin Security</h3></div><div class="card-body"><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><div class="form-group"><label>New Admin Password</label><input type="password" name="new_password" class="form-control" minlength="10"></div><div class="form-group"><label>Confirm Password</label><input type="password" name="confirm_password" class="form-control" minlength="10"></div><button class="btn btn-pink">Change Password</button></form></div></div></div></section></div><?php require __DIR__.'/comman/footer.php'; ?>